discrete WindEnergySystem
port:
    event input real WindSpeed;
    event output real Status;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(WindSpeed) then
            transition(RunningState);
        end;
    end;

    state RunningState
        when entry() then
            statehold(0);
        end;
        when receive(WindSpeed) then
            transition(StandbyState);
        end;
    end;
end;
end;

discrete SolarEnergySystem
port:
    event input real LightIntensity;
    event output real Status;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(LightIntensity) then
            transition(RunningState);
        end;
    end;

    state RunningState
        when entry() then
            statehold(0);
        end;
        when receive(LightIntensity) then
            transition(StandbyState);
        end;
    end;
end;
end;

discrete EnergyManagementSystem
port:
    event input real BatteryLevel;
    event input real AvailableEnergy;
    event input real LoadDemand;
    event output real Status;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(BatteryLevel) then
            transition(ChargingState);
        end;
        when receive(LoadDemand) then
            transition(DischargingState);
        end;
    end;

    state ChargingState
        when entry() then
            statehold(0);
        end;
        when receive(BatteryLevel) then
            transition(StandbyState);
        end;
    end;

    state DischargingState
        when entry() then
            statehold(0);
        end;
        when receive(BatteryLevel) then
            transition(StandbyState);
        end;
    end;
end;
end;

couple HybridPowerSystem
import architectureModels.WindEnergySystem as Wind;
import architectureModels.SolarEnergySystem as Solar;
import architectureModels.EnergyManagementSystem as EMS;

part:
    Wind windInstance;
    Solar solarInstance;
    EMS emsInstance;

connection:
    connect(windInstance.Status, emsInstance.BatteryLevel);
    connect(solarInstance.Status, emsInstance.AvailableEnergy);
    connect(emsInstance.Status, windInstance.WindSpeed);
    connect(emsInstance.Status, solarInstance.LightIntensity);
end;
